  if (f.id === 'laFI') { if (!s.code || fd('vcode') !== s.code) return err('인증번호를 확인하세요.'); const p = laPhone(fd('phone')); const r = laRoom() || {};
    F.found = [...(r.members || []).filter(m => m.acct && m.acct.email && (m.acct.phone === p || m.phone === p)).map(m => ({ email: m.acct.email, login: m.acct.login })), ...(r.pacct || []).filter(x => x.phone === p).map(x => ({ email: x.email, login: x.login })), ...Object.values(laCache()).filter(x => x && !x.del && x.phone === p && x.email).map(x => ({ email: x.email, login: x.login }))].filter((x, i, A) => A.findIndex(y => y.email === x.email) === i);
    F.step = 2; LA.fv = null; lrender(); return; }
  if (f.id === 'laFP') { const id = fd('lid').toLowerCase(); const acc = laFind(id); if (!s.code || fd('vcode') !== s.code) return err('인증번호를 확인하세요.'); if (!acc) return err('가입한 계정을 찾을 수 없습니다.'); if ((F.vm || 'pass') === 'pass' && laPhone(fd('phone')) !== acc.phone) return err('가입한 휴대폰 번호와 다릅니다.'); F.id = id; F.step = 2; LA.fv = null; lrender(); return; }
